python3 - << 'PYEOF'
import json

# Read current flow
with open('/work/output/artifacts/skill-flow-devcon-billing-discrepancy-detector/BillingDiscrepancyDetector/BillingDiscrepancyDetector/BillingDiscrepancyDetector.flow') as f:
    flow = json.load(f)

# Read definitions to extract
end_def = json.load(open('/tmp/end_def_clean.json'))
merge_def = json.load(open('/tmp/merge_def_clean.json'))
script_def = json.load(open('/tmp/script_def_clean.json'))

# Build nodes: start (existing), queryErpRecords1 (existing), queryCrmRecord1 (existing),
# plus merge, computeResult (script), end

# Keep existing nodes but update start to add outputs
existing_nodes = {n['id']: n for n in flow['nodes']}

# Update start node with outputs
existing_nodes['start']['outputs'] = {
    "output": {
        "type": "object",
        "description": "The return value of the trigger.",
        "source": "=result.response",
        "var": "output"
    }
}

# Add merge node
merge_node = {
    "id": "mergeBranches",
    "type": "core.logic.merge",
    "typeVersion": "1.0",
    "display": {"label": "Merge Branches"},
    "inputs": {}
}

# Add computeResult script node
# Script: compute invoiced, look up contracted amount for the matching lineNumber, totalOvercharge, discrepancyCount
compute_script = """
var erpRows = $vars.queryErpRecords1.output.value;
var crmRows = $vars.queryCrmRecord1.output.value;
var disputedLineNumber = $vars.start.output.disputedLineNumber;
var disputedUnitPrice = $vars.start.output.disputedUnitPrice;
var disputedQuantity = $vars.start.output.disputedQuantity;
var invoiceNumber = $vars.start.output.invoiceNumber;

var invoiced = disputedUnitPrice * disputedQuantity;

var matchedRow = null;
if (erpRows && erpRows.length > 0) {
    for (var i = 0; i < erpRows.length; i++) {
        if (erpRows[i].lineNumber === disputedLineNumber) {
            matchedRow = erpRows[i];
            break;
        }
    }
}

var contracted = matchedRow ? matchedRow.amount : 0;
var diff = invoiced - contracted;
var totalOvercharge = diff > 0 ? diff : 0;
var discrepancyCount = diff > 0 ? 1 : 0;

var matchedInvoiceNumber = (erpRows && erpRows.length > 0) ? erpRows[0].invoiceNumber : invoiceNumber;

var accountTier = "";
if (crmRows && crmRows.length > 0) {
    accountTier = crmRows[0].accountTier;
}

return {
    totalOvercharge: totalOvercharge,
    discrepancyCount: discrepancyCount,
    matchedInvoiceNumber: matchedInvoiceNumber,
    accountTier: accountTier
};
""".strip()

compute_node = {
    "id": "computeResult",
    "type": "core.action.script",
    "typeVersion": "1.0",
    "display": {"label": "Compute Discrepancy"},
    "inputs": {
        "script": compute_script
    },
    "outputs": {
        "output": {
            "type": "object",
            "description": "The return value of the script",
            "source": "=result.response",
            "var": "output"
        },
        "error": {
            "type": "object",
            "description": "Error information if the script fails",
            "source": "=result.Error",
            "var": "error"
        }
    }
}

# Add end node with output mapping
end_node = {
    "id": "end",
    "type": "core.control.end",
    "typeVersion": "1.0",
    "display": {"label": "End"},
    "inputs": {},
    "outputs": {
        "totalOvercharge": {
            "source": "=js:$vars.computeResult.output.totalOvercharge"
        },
        "discrepancyCount": {
            "source": "=js:$vars.computeResult.output.discrepancyCount"
        },
        "matchedInvoiceNumber": {
            "source": "=js:$vars.computeResult.output.matchedInvoiceNumber"
        },
        "accountTier": {
            "source": "=js:$vars.computeResult.output.accountTier"
        }
    }
}

flow['nodes'] = [
    existing_nodes['start'],
    existing_nodes['queryErpRecords1'],
    existing_nodes['queryCrmRecord1'],
    merge_node,
    compute_node,
    end_node
]

# Edges: parallel fan-out from start to both DS nodes, then merge, then compute, then end
flow['edges'] = [
    {"id": "e-start-erp", "sourceNodeId": "start", "sourcePort": "output", "targetNodeId": "queryErpRecords1", "targetPort": "input"},
    {"id": "e-start-crm", "sourceNodeId": "start", "sourcePort": "output", "targetNodeId": "queryCrmRecord1", "targetPort": "input"},
    {"id": "e-erp-merge", "sourceNodeId": "queryErpRecords1", "sourcePort": "output", "targetNodeId": "mergeBranches", "targetPort": "input"},
    {"id": "e-crm-merge", "sourceNodeId": "queryCrmRecord1", "sourcePort": "output", "targetNodeId": "mergeBranches", "targetPort": "input"},
    {"id": "e-merge-compute", "sourceNodeId": "mergeBranches", "sourcePort": "output", "targetNodeId": "computeResult", "targetPort": "input"},
    {"id": "e-compute-end", "sourceNodeId": "computeResult", "sourcePort": "success", "targetNodeId": "end", "targetPort": "input"}
]

# Add missing definitions
existing_defs = {d['nodeType']: d for d in flow['definitions']}
for d in [end_def, merge_def, script_def]:
    nt = d.get('nodeType', d.get('type', ''))
    if nt not in existing_defs:
        flow['definitions'].append(d)

# Variables: globals (in/out), nodes (add merge, computeResult, end)
# In variables: invoiceNumber, accountNumber, disputedLineNumber, disputedUnitPrice, disputedQuantity
# Out variables: totalOvercharge, discrepancyCount, matchedInvoiceNumber, accountTier
flow['variables'] = {
    "globals": [
        {"id": "invoiceNumber", "direction": "in", "type": "string", "triggerNodeId": "start", "description": "The invoice number to look up"},
        {"id": "accountNumber", "direction": "in", "type": "string", "triggerNodeId": "start", "description": "The account number to look up"},
        {"id": "disputedLineNumber", "direction": "in", "type": "number", "triggerNodeId": "start", "description": "The disputed line number"},
        {"id": "disputedUnitPrice", "direction": "in", "type": "number", "triggerNodeId": "start", "description": "The disputed unit price"},
        {"id": "disputedQuantity", "direction": "in", "type": "number", "triggerNodeId": "start", "description": "The disputed quantity"},
        {"id": "totalOvercharge", "direction": "out", "type": "number", "description": "Total overcharge amount"},
        {"id": "discrepancyCount", "direction": "out", "type": "number", "description": "Number of discrepancies found"},
        {"id": "matchedInvoiceNumber", "direction": "out", "type": "string", "description": "The matched invoice number from ERP"},
        {"id": "accountTier", "direction": "out", "type": "string", "description": "The account tier from CRM"}
    ],
    "nodes": [
        {"id": "start.output", "type": "object", "description": "Data passed when manually triggering the workflow.", "binding": {"nodeId": "start", "outputId": "output"}},
        {"id": "queryErpRecords1.output", "type": "object", "description": "The return value of the connector.", "binding": {"nodeId": "queryErpRecords1", "outputId": "output"}},
        {"id": "queryErpRecords1.error", "type": "object", "description": "Error information if the node fails", "binding": {"nodeId": "queryErpRecords1", "outputId": "error"}},
        {"id": "queryCrmRecord1.output", "type": "object", "description": "The return value of the connector.", "binding": {"nodeId": "queryCrmRecord1", "outputId": "output"}},
        {"id": "queryCrmRecord1.error", "type": "object", "description": "Error information if the node fails", "binding": {"nodeId": "queryCrmRecord1", "outputId": "error"}},
        {"id": "mergeBranches.output", "type": "object", "binding": {"nodeId": "mergeBranches", "outputId": "output"}},
        {"id": "computeResult.output", "type": "object", "binding": {"nodeId": "computeResult", "outputId": "output"}},
        {"id": "computeResult.error", "type": "object", "binding": {"nodeId": "computeResult", "outputId": "error"}}
    ]
}

# Layout
flow['layout'] = {
    "nodes": {
        "start": {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False},
        "queryErpRecords1": {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False},
        "queryCrmRecord1": {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False},
        "mergeBranches": {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False},
        "computeResult": {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False},
        "end": {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False}
    }
}

with open('/work/output/artifacts/skill-flow-devcon-billing-discrepancy-detector/BillingDiscrepancyDetector/BillingDiscrepancyDetector/BillingDiscrepancyDetector.flow', 'w') as f:
    json.dump(flow, f, indent=2)
print("WROTE flow OK")
PYEOF

